const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const button=(text,action,cls='')=>{const n=el('button',cls,text);n.type='button';n.dataset.action=action;return n};
const svgIcon=paths=>{const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');for(const d of paths){const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',d);svg.append(path)}return svg};
const actionIcon=(action,cls,label,paths)=>{const n=button('',action,`row-action-button ${cls}`);n.title=label;n.setAttribute('aria-label',label);n.append(svgIcon(paths));return n};
const lower=v=>String(v??'').toLocaleLowerCase('ja');
export const displayPath=value=>{const path=String(value??'').replaceAll('/','\\');return path.slice(0,8).toLowerCase()==='\\\\?\\unc\\'?`\\\\${path.slice(8)}`:path.slice(0,4).toLowerCase()==='\\\\?\\'?path.slice(4):path};
const isPdf=m=>m.target_type==='file'&&/\.pdf$/i.test(m.path);
export function materialIcon(m){
  if(m.target_type==='folder')return{label:'📁',kind:'folder'};
  if(m.target_type==='url')return{label:'↗',kind:'url'};
  const ext=(m.path.split('.').pop()??'').toLocaleLowerCase();
  if(ext==='pdf')return{label:'PDF',kind:'pdf'};
  if(['doc','docx'].includes(ext))return{label:'W',kind:'word'};
  if(['xls','xlsx','csv'].includes(ext))return{label:'X',kind:'excel'};
  if(['ppt','pptx'].includes(ext))return{label:'P',kind:'powerpoint'};
  if(['png','jpg','jpeg','gif','webp','svg'].includes(ext))return{label:'▧',kind:'image'};
  if(['txt','md','rtf'].includes(ext))return{label:'≡',kind:'text'};
  return{label:'▤',kind:'file'};
}
export function visibleMaterials(config,selectedGroupId,query){const names=new Map((config?.groups??[]).map(g=>[g.id,g.name])),q=lower(query).trim();return(config?.materials??[]).filter(m=>q?lower(`${m.name} ${names.get(m.group_id)??''}`).includes(q):m.group_id===selectedGroupId).sort((a,b)=>a.order-b.order)}
export function noticeTone(value){const code=typeof value==='string'?value:value?.code??value?.outcome;return code==='saved'||['activated','launched','not_trackable'].includes(code)?'success':code?'warning':'neutral'}
export function noticeMessage(value){const code=typeof value==='string'?value:value?.code??value?.outcome;return noticeText[code]??''}
export function batchSummary(results){const success=results.filter(r=>!r.error).length;return `一括起動: 成功 ${success}件 / 失敗 ${results.length-success}件`}
export function pdfPageKeyDirection(event){
  if(event.repeat||event.isComposing||event.keyCode===229||event.ctrlKey||event.metaKey||event.altKey)return 0;
  if(event.key==='PageUp')return -1;
  if(event.key==='PageDown')return 1;
  return 0;
}
export function pdfArrowBoundaryDirection(event,scrollTop,clientHeight,scrollHeight){
  if(event.repeat||event.isComposing||event.keyCode===229||event.ctrlKey||event.metaKey||event.altKey)return 0;
  if(event.key==='ArrowUp'&&scrollTop<=0)return -1;
  if(event.key==='ArrowDown'&&scrollTop+clientHeight>=scrollHeight-1)return 1;
  return 0;
}

